{
  "title": "Snack, Sip, and a Proper Meal",
  "summary": "A slower day built around Rin's appetite, with a market wander, a temple kept, and a proper dinner to close.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Shoes off, phone down, eyes up. The thousand statues stay, so we start here before the market wakes.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Rin eats her way through the day, so we graze here. Street food counts as culture if you chew slowly.",
      "must_do_id": null
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "A quiet bowl before the afternoon. Cheap, warm, and exactly what a market morning deserves.",
      "must_do_id": null
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle stroll to settle the snacks. The old street does the talking.",
      "must_do_id": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with a little theatre. Rin gets her proper meal, and the rest of us get to watch.",
      "must_do_id": null
    }
  ]
}
